export function installMarasenTrainers(expansion,voices={}){for(const t of MARASEN_TRAINERS){if(!expansion.trainers.some(x=>x.id===t.id))expansion.trainers.push(t);voices[t.id]={before:t.before,after:t.after,repeat:'This challenge is recorded. The people here still have work to do.'};}}
export function marasenRoute(room){const entry=VERDANT_ROAD.find(r=>r[0]===room),branch=MARASEN_BRANCHES[room];if(!entry&&!branch&&!room.startsWith('marasen'))return null;if(!entry)return {room,area:{id:room,name:branch?.name||'Marasen',rate:'LOW'},tables:[]};return {room,explorationTable:true,encounterPacing:true,area:{id:room,name:entry[1],rate:'NORMAL'},tables:['DAY','NIGHT'].map((phase,p)=>({id:room+'-'+phase,area_id:room,phase,slots:entry[3+p].map((id,i)=>({species_id:id,min_level:i===4?24:55,max_level:i===4?30:61,weight:[35,28,22,14,1][i],authoredSlot:true,rarity:i===4?'Very rare · first-form pseudo':i===3?'Uncommon':'Common'}))}))};}
